VALUES
  ('ch2_AHB-033', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ की ताम्रपाषाणिक बस्ती जिस टीले के नीचे मिली, उस टीले का नाम क्या था?', 'धूलकोट; राजस्थान बोर्ड की कक्षा 10 की पुस्तक में ‘धूलकोट’ का अर्थ मिट्टी का टीला बताया गया है।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-033 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; PDF page-image review लंबित।', 'NEEDS_REVIEW', 0.80, 'f553bcd6b15c494e7871e08818cbc405527f716251fc0c8b2d89066b6e911102', NULL),
  ('ch2_AHB-034', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ के दफन-साक्ष्यों में मृतकों के साथ कौन-सी वस्तुएँ रखने का उल्लेख मिलता है?', 'आभूषण और गहने; पाठ्यपुस्तक के लेखक इसे मृत्यु के बाद जीवन में विश्वास का संकेत मानते हैं।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-034 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; विश्वास-संबंधी कथन पाठ्यपुस्तक की व्याख्या है।', 'NEEDS_REVIEW', 0.80, '232abf77a6cfd51316590302677ed555c8f492a93cf2d070a6d07c6cbd9adfa1', NULL),
  ('ch2_AHB-035', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ से मिले किस प्रकार के ब्लॉकों को वस्त्र-रंगाई और छपाई से जोड़ा गया है?', 'ऐसे ब्लॉक मिले जिन्हें कपड़े की रंगाई और छपाई के काम का संकेत माना गया।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-035 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; कार्य-निर्धारण स्रोत की व्याख्या है।', 'NEEDS_REVIEW', 0.80, '327039bb064adb6587c03dfd25e6981679a63c134abf26de1fc55729ac56785e', NULL),
  ('ch2_AHB-036', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'गिलूंड में पहली और बाद की प्रमुख खुदाइयों का नेतृत्व किन्होंने और कब किया?', 'पहली खुदाई 1957–58 में बी. बी. लाल के निर्देशन में हुई; बाद में वी. एस. शिंदे और ग्रेगरी पोसेल ने 1998–2003 में उत्खनन किया।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-036 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; उत्खनन इतिहास पाठ्यपुस्तक के अनुसार।', 'NEEDS_REVIEW', 0.80, '7c685fdf36960a8c668ba0263c7f324403cee67e3de395de09ce92173b743c27', NULL),
  ('ch2_AHB-037', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'राजस्थान बोर्ड की पुस्तक के अनुसार गिलूंड की ताम्रपाषाणिक संस्कृति के कितने चरण मिले और दूसरे चरण का संभावित आरंभ कब माना गया?', 'दो चरण; दूसरा चरण संभवतः दूसरी सहस्राब्दी ईसा पूर्व के मध्य में शुरू हुआ।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-037 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; ‘संभवतः’ स्रोत की अनिश्चितता सुरक्षित रखता है।', 'NEEDS_REVIEW', 0.80, '427366949966a2e2e2688975d12ee5e6ad42517223232bb873001afe1b751d9c', NULL),
  ('ch2_AHB-038', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'राजस्थान बोर्ड की पुस्तक में गिलूंड के ताम्रपाषाणिक मृद्भांड कितने और किन व्यापक वर्गों में बाँटे गए हैं?', 'पाँच—लाल, काले-लाल, चित्रित, बफ (हल्के पीले-भूरे) और धूसर मृद्भांड।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-038 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; वर्गीकरण पाठ्यपुस्तक के अनुसार।', 'NEEDS_REVIEW', 0.80, '3ccf38f6f4dae8cea77a26394673b974d7f77e66888c62cdfa47f034a3f7aaa9', NULL),
  ('ch2_AHB-039', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'गिलूंड से मृद्भांडों के अलावा कौन-सी तीन प्रमुख वस्तुएँ मिलने का उल्लेख है?', 'मिट्टी के खिलौने, मनके और हाथीदाँत की चूड़ियाँ।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-039 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4।', 'NEEDS_REVIEW', 0.80, '35ef6639b8ffe8c9a6f8a7052f0ab28e994024bced5e80096919ea18893e2c02', NULL),
  ('ch2_AHB-040', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'गिलूंड और आहड़ के बीच पकी ईंटों के प्रयोग में क्या अंतर बताया गया है?', 'गिलूंड में पकी ईंटों के उपयोग और निर्माण, दोनों के साक्ष्य मिले; पुस्तक के अनुसार आहड़ में पकी ईंटों का प्रयोग नहीं था।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-040 — S32 — राजस्थान माध्यमिक शिक्षा बोर्ड, History and Culture of Rajasthan, कक्षा 10, मुद्रित पृ. 4; स्थल-विशिष्ट अंतर पाठ्यपुस्तक के अनुसार।', 'NEEDS_REVIEW', 0.80, '4113b7b850473a314d76cdfcea4884dda0d8642c0bcdc10541c12875acd33949', NULL),
  ('ch2_AHB-041', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ के प्रारंभिक उत्खनन और स्थल-परिचय का श्रेय दो स्रोतों में कैसे अलग दर्ज है?', 'राजस्थान बोर्ड की पुस्तक 1953 में अक्षयकीर्ति व्यास द्वारा खुदाई शुरू होने का उल्लेख करती है; बी. आर. मीणा का लेख 1954–55 में आर. सी. अग्रवाल द्वारा स्थल प्रकाश में लाए जाने का श्रेय देता है। दोनों स्रोतों का विवरण अलग रखें।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'AHB-041 — S32, कक्षा 10 की पुस्तक, मुद्रित पृ. 4: 1953 में अक्षयकीर्ति व्यास; S23, B.R. Meena, Puratattva 16, मुद्रित पृ. 20: R.C. Agrawal, 1954–55, https://ignca.gov.in/Asi_data/74144.pdf; स्रोतों का श्रेय-विवरण अलग है, स्वतंत्र समाधान लंबित।', 'NEEDS_REVIEW', 0.80, 'd4c21f6cc43e619eaf54338be5b727a63fcfe21af4e1218ee36a187b1b7c2639', NULL),
  ('ch2_AHB-042', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'शोध के अनुसार आहड़-बनास समुदायों के हड़प्पा समुदाय से बढ़ते व्यापारिक संपर्क लगभग कब से बताए गए हैं?', 'लगभग 2600 ईसा पूर्व के बाद; यह प्रकाशित अध्ययन का क्षेत्रीय संपर्क संबंधी निष्कर्ष है।', 'hi', 'https://ignca.gov.in/Asi_data/87125.pdf', 'AHB-042 — S30 — Shinde, Possehl और Sinha-Deshpande, The Ceramic Assemblage in Protohistoric Mewar, Puratattva 32 (2001–02), मुद्रित पृ. 5–6; संपर्क संबंधी कथन लेखकों का निष्कर्ष है।', 'NEEDS_REVIEW', 0.80, 'ac709b3725bb836be891efa458ede547e45b610a3874709398377ae7caa078e4', NULL)
ON CONFLICT DO NOTHING;

